import { getPlanLimits } from \"@/config/plan-limits\";
import { emit } from \"@/lib/event-bus\";
import { newId } from \"@/lib/id\";
import * as invoiceRepo from \"@/server/repositories/invoice-repository\";
import { toIsoTimestamp } from \"@/types/common\";
import type { BillingInterval, Subscription } from \"@/types/billing\";

export function periodEnd(start: Date, interval: BillingInterval): Date {
  const end = new Date(start);
  const day = end.getUTCDate();
  end.setUTCDate(1);
  end.setUTCMonth(end.getUTCMonth() + (interval === \"annual\" ? 12 : 1));
  const last = new Date(end);
  last.setUTCMonth(last.getUTCMonth() + 1, 0);
  end.setUTCDate(Math.min(day, last.getUTCDate()));
  return end;
}

export function fullCharge(subscription: Subscription): number {
  return getPlanLimits(subscription.plan).priceCentsPerSeatMonthly * subscription.seats *
    (subscription.interval === \"annual\" ? 12 : 1);
}

export function prorate(amount: number, subscription: Subscription, now: Date): number {
  const day = 86_400_000;
  const end = new Date(subscription.currentPeriodEnd).getTime();
  const days = Math.max(1, Math.round((end - new Date(subscription.currentPeriodStart).getTime()) / day));
  const left = Math.max(0, Math.ceil((end - now.getTime()) / day));
  return Math.floor(Math.max(0, amount) * left / days);
}

export async function issueInvoice(subscription: Subscription, amountCents: number, now: Date): Promise<void> {
  if (amountCents <= 0) return;
  const invoice = await invoiceRepo.insertInvoice(subscription.orgId, {
    orgId: subscription.orgId, number: "'`INV-${newId()}`, amountCents, currency: "usd",
    periodStart: subscription.currentPeriodStart, periodEnd: subscription.currentPeriodEnd, paidAt: null,
  });
  await emit("billing.invoice_issued", {
    orgId: subscription.orgId, actorId: null, occurredAt: toIsoTimestamp(now),
    invoiceId: invoice.id, invoiceNumber: invoice.number, amountCents,
    periodStart: invoice.periodStart, periodEnd: invoice.periodEnd,
  });
}
