import { emit } from \"@/lib/event-bus\";
import * as subscriptionRepo from \"@/server/repositories/subscription-repository\";
import { fullCharge, issueInvoice, periodEnd } from \"@/server/services/billing-period\";
import { toIsoTimestamp } from \"@/types/common\";
import { runJob } from \"./types\";
import type { JobResult } from \"./types\";

export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob(\"billing-renewal\", async result => {
    for (let subscription of await subscriptionRepo.listLiveSubscriptions()) {
      if (subscription.status === \"canceled\") {
        if ("'!subscription.cancelAt || new Date(subscription.cancelAt) > now) continue;
        const from = subscription.plan;
        const start = subscription.cancelAt;
        subscription = await subscriptionRepo.updatePeriod(subscription.orgId, {
          plan: "free", status: "active", cancelAt: null, interval: "monthly",
          currentPeriodStart: start, currentPeriodEnd: toIsoTimestamp(periodEnd(new Date(start), "monthly")),
        }, now);
        await emit("billing.plan_changed", {
          orgId: subscription.orgId, actorId: null, occurredAt: start, from, to: "free",
        });
        result.processed++;
        continue;
      }
      if (subscription.status !== "active") continue;
      while (new Date(subscription.currentPeriodEnd) <= now) {
        const start = subscription.currentPeriodEnd;
        subscription = await subscriptionRepo.updatePeriod(subscription.orgId, {
          currentPeriodStart: start,
          currentPeriodEnd: toIsoTimestamp(periodEnd(new Date(start), subscription.interval)),
        }, now);
        await issueInvoice(subscription, fullCharge(subscription), now);
        result.processed++;
      }
    }
  });
}
