    expect(notices).toHaveLength(3);
    expect(notices.every(n => n.recipientId === tenant.org.ownerId && n.kind === \"invoice_issued\")).toBe(true);
    const audit = getDb().select().from(activityEvents).where(eq(activityEvents.orgId, tenant.org.id)).all();
    expect(audit.filter(a => a.action === \"billing.invoice_issued\")).toHaveLength(3);
  } finally { off(); offAudit(); }
});

it(\"defers cancellation until its date and skips archived, trialing and past due subscriptions\", async () => {
  const now = date(\"2026-06-01T00:00:00Z\");
  for (const state of [\"trialing\", \"past_due\", \"active\", \"canceled\"] as const) {
    const tenant = await createTenant("'`renewal-${state}`, "starter");
    await subscriptionRepo.updatePeriod(tenant.org.id, {
      status: state, currentPeriodStart: toIsoTimestamp(date("2026-01-01T00:00:00Z")),
      currentPeriodEnd: toIsoTimestamp(date("2026-02-01T00:00:00Z")),
      cancelAt: state === "canceled" ? toIsoTimestamp(date("2026-06-02T00:00:00Z")) : null,
    }, now);
    if (state === "active") await orgRepo.archiveOrg(tenant.org.id);
    const before = await subscriptionRepo.findSubscription(tenant.org.id);
    await runBillingRenewalJob(now);
    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toEqual(before);
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
  }
});

it("cancels to free without an invoice and is replay safe even after several months", async () => {
  const tenant = await createTenant("renewal-cancellation", "growth");
  const now = date("2026-06-15T00:00:00Z");
  await subscriptionRepo.updatePeriod(tenant.org.id, {
    status: "canceled", cancelAt: toIsoTimestamp(date("2026-02-15T00:00:00Z")),
  }, now);
  const seen: string[] = [];
  const off = subscribe("billing.plan_changed", p => { if (p.orgId === tenant.org.id) seen.push(p.to); });
  try {
    await runBillingRenewalJob(now);
    const before = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(before).toMatchObject({ plan: "free", status: "active", cancelAt: null, interval: "monthly" });
    await runBillingRenewalJob(now);
    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toEqual(before);
    expect(seen).toEqual(["free"]);
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
  } finally { off(); }
});

